            `).join('')}
          </div>
        `;
        const statusBadgeCls = warn > 0 ? 'warn' : 'ok';
        const badgeLabel = warn > 0 ? `⚠️ ${warn} ملاحظات` : `✓ معتمد (0 أخطاء)`;
        observerHtml = `
          <div class="observer-box proposal-audit-section" data-review="${this.escapeHtml(msg.observerReview).slice(0,300)}">
