          const r=await fetch(base+'/v1/chat/completions',{method:'POST', headers:{'Authorization':`Bearer ${key}`,'Content-Type':'application/json'}, body: JSON.stringify({model:model, messages:[{role:'user', content:`[${service}] ${prompt}`}]})});
