            } else {
              aiMsg.content='⚠️ Generation failed `'+modelId+'`: '+(j.error.message||JSON.stringify(j).slice(0,600));
            }
          }
        } else {
          aiMsg.content='```json\n'+JSON.stringify(j,null,2).slice(0,2000)+'\n```';
        }
