  window.UsagePieController = UsagePieController;

  // ─────────────────────────────────────────────────────────────────
  // 6b. CLIENT-SIDE DOCUMENT RAG ENGINE (Smart Chunking & Semantic Search)
  // ─────────────────────────────────────────────────────────────────
  const DocumentRAGEngine = window.DocumentRAGEngine || {
    dbName: 'xv1_rag_vault',
    storeName: 'documents',
    _db: null,

    async initDB() {
      if (this._db) return this._db;
      return new Promise((resolve) => {
        try {
          if (typeof indexedDB === 'undefined') return resolve(null);
          const req = indexedDB.open(this.dbName, 1);
          req.onupgradeneeded = (e) => {
            const db = e.target.result;
            if (!db.objectStoreNames.contains(this.storeName)) {
              db.createObjectStore(this.storeName, { keyPath: 'name' });
            }
          };
          req.onsuccess = (e) => {
            this._db = e.target.result;
            resolve(this._db);
          };
          req.onerror = () => resolve(null);
        } catch(e) {
          resolve(null);
        }
      });
    },

    async saveDoc(name, text, chunks) {
      try {
        const db = await this.initDB();
        if (db) {
          const tx = db.transaction(this.storeName, 'readwrite');
          const store = tx.objectStore(this.storeName);
          store.put({ name, text: text.slice(0, 100000), chunks, savedAt: Date.now() });
        }
      } catch(e) {}
      try {
        sessionStorage.setItem('doc_' + name, JSON.stringify(chunks.slice(0, 40)));
      } catch(e) {}
    },

    chunkText(text, chunkSize = 500, overlap = 70) {
      if (!text || text.length <= chunkSize) return [text];
      const chunks = [];
      let i = 0;
      while (i < text.length) {
        let end = Math.min(i + chunkSize, text.length);
        if (end < text.length) {
          const nextBreak = text.lastIndexOf('\n', end);
          if (nextBreak > i + 150) end = nextBreak;
          else {
            const nextDot = text.lastIndexOf('. ', end);
            if (nextDot > i + 150) end = nextDot + 1;
          }
        }
        const chunk = text.slice(i, end).trim();
        if (chunk) chunks.push(chunk);
        i = end - overlap;
        if (i >= text.length - overlap) break;
      }
      return chunks;
    },

    searchRelevantChunks(query, chunks, maxChunks = 4) {
      if (!chunks || !chunks.length) return [];
      if (chunks.length <= maxChunks) return chunks;

      const cleanQ = (query || '').toLowerCase().replace(/[^\w\u0600-\u06FF\s]/g, ' ');
      const qTokens = cleanQ.split(/\s+/).filter(t => t.length > 2);
      if (!qTokens.length) return chunks.slice(0, maxChunks);

      const scored = chunks.map((chunk, idx) => {
        const lower = chunk.toLowerCase();
        let score = 0;
        for (const token of qTokens) {
          const regex = new RegExp(token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
          const matches = (lower.match(regex) || []).length;
          if (matches > 0) {
            score += matches * (1 + Math.min(token.length, 8) / 4);
          }
        }
        return { chunk, score, idx };
      });

      scored.sort((a, b) => b.score - a.score);
      const top = scored.slice(0, maxChunks).filter(s => s.score > 0);
      return top.length ? top.map(t => t.chunk) : chunks.slice(0, maxChunks);
    }
  };
  try { window.DocumentRAGEngine = DocumentRAGEngine; } catch(e) {}

  // ─────────────────────────────────────────────────────────────────
  // 6c. LIVE REAL-TIME WEB SEARCH ENGINE
  // ─────────────────────────────────────────────────────────────────
  const WebSearchEngine = window.WebSearchEngine || {
    isWebSearchIntent(query) {
      const q = (query || '').toLowerCase().trim();
      if (!q) return false;
      const searchKeywords = [
        'ابحث عن', 'ابحث في النت', 'بحث في الويب', 'آخر أخبار', 'اخبار اليوم', 'سعر', 'من هو', 'أين يقع',
        'search', 'latest news', 'what is the price', 'who is', 'today', '2025', '2026', 'current status',
        'طقس', 'weather', 'نتيجة مباراة', 'موقع', 'حدث'
      ];
      return searchKeywords.some(kw => q.includes(kw));
    },

    cleanSearchQuery(query) {
      return (query || '')
        .replace(/^(ابحث عن|ابحث في النت عن|ابحث في الويب عن|search for|google|search)\s+/i, '')
        .replace(/[؟?؟!]/g, '')
        .slice(0, 120)
        .trim();
    },

    async search(query) {
      const clean = this.cleanSearchQuery(query);
      if (!clean) return null;

      try {
        const ddgUrl = `https://api.duckduckgo.com/?q=${encodeURIComponent(clean)}&format=json&no_html=1&skip_disambig=1`;
        const res = await fetch(`https://api.allorigins.win/raw?url=${encodeURIComponent(ddgUrl)}`, {
          signal: AbortSignal.timeout(3600)
        });
        if (res.ok) {
          const data = await res.json();
          const results = [];
          if (data.AbstractText) {
            results.push({ title: data.Heading || clean, snippet: data.AbstractText, url: data.AbstractURL || 'DuckDuckGo' });
          }
          if (Array.isArray(data.RelatedTopics)) {
            data.RelatedTopics.slice(0, 3).forEach(topic => {
              if (topic.Text && topic.FirstURL) {
                results.push({ title: topic.Text.split(' - ')[0] || clean, snippet: topic.Text, url: topic.FirstURL });
              }
            });
          }
          if (results.length > 0) return results;
        }
      } catch (e) {}

      try {
        const isAr = /[\u0600-\u06FF]/.test(clean);
        const lang = isAr ? 'ar' : 'en';
        const wikiUrl = `https://${lang}.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(clean.replace(/\s+/g, '_'))}`;
        const wikiRes = await fetch(wikiUrl, { signal: AbortSignal.timeout(2800) });
        if (wikiRes.ok) {
          const wData = await wikiRes.json();
          if (wData.extract) {
            return [{
              title: wData.title || clean,
              snippet: wData.extract,
              url: wData.content_urls?.desktop?.page || `https://${lang}.wikipedia.org`
            }];
          }
        }
      } catch (e) {}

      return null;
    }
  };
  try { window.WebSearchEngine = WebSearchEngine; } catch(e) {}

  // ─────────────────────────────────────────────────────────────────
  // 7. CHAT CONTROLLER & STREAM ORCHESTRATOR — Extracted to modules/chat-engine.js
  // ─────────────────────────────────────────────────────────────────
  const ChatEngine = window.ChatEngine || {
    preparePayload(userText) {
      let textForPayload = userText.trim();
      const currentAttachments = [...state.attachments];

      const attachedTexts = currentAttachments.filter(a => !a.type.startsWith('image/'));
      if (attachedTexts.length > 0) {
        const fileContexts = attachedTexts.map(f => {
          const raw = f.textContent || '';
          if (raw.length <= 1500) {
            return `--- محتوى الملف المرفق: ${f.name} ---\n${raw}\n--- نهاية الملف ---`;
          }
          const chunks = DocumentRAGEngine.chunkText(raw);
          DocumentRAGEngine.saveDoc(f.name, raw, chunks);
          const relevant = DocumentRAGEngine.searchRelevantChunks(userText, chunks, 4);
          return `--- مقتطفات دلالية مطابقة من المستند المرفق: ${f.name} (${chunks.length} مقطع مفهرس محلياً) ---\n${relevant.join('\n\n---\n\n')}\n--- نهاية المقتطفات المفهرسة ---`;
        }).join('\n\n');
        textForPayload = textForPayload ? `${textForPayload}\n\n${fileContexts}` : fileContexts;
      }

      const attachedImages = currentAttachments.filter(a => a.type.startsWith('image/'));
      if (attachedImages.length > 0 && !textForPayload) {
        textForPayload = 'يرجى فحص هذه الصورة المرفقة والإجابة عنها.';
      }

      return { textForPayload, currentAttachments };
    },

    getAdaptiveConfig(tier) {
      // efficient high-quality: HIGH uses more of 1M when needed, but still throttled
      if (tier === 'HIGH') return { recentCount: 18, maxBriefingChars: 8000 };
      if (tier === 'FAST') return { recentCount: 6, maxBriefingChars: 800 };
      return { recentCount: 12, maxBriefingChars: 3500 };
    },

    generateBriefing(conv, tier) {
      if (!conv || !Array.isArray(conv.messages) || conv.messages.length <= 6) return '';
      const cfg = this.getAdaptiveConfig(tier);
      const title = conv.title || 'محادثة';

      const allMsgs = conv.messages.filter(m => m.content && (m.role === 'user' || m.role === 'ai'));
      if (allMsgs.length <= cfg.recentCount) return '';

      const olderMsgs = allMsgs.slice(0, allMsgs.length - cfg.recentCount);
      const userGoals = olderMsgs.filter(m => m.role === 'user').map(m => m.content.slice(0, 140).replace(/\n/g, ' ').trim()).slice(-4);
      const aiDecisions = olderMsgs.filter(m => m.role === 'ai').map(m => m.content.slice(0, 150).replace(/\n/g, ' ').trim()).slice(-4);

      let memoryDigest = `🧠 [الذاكرة التراكمية للمحادثة (${title})]:\n` +
        `- عدد التبادلات السابقة المؤرشفة: ${olderMsgs.length}\n` +
        `- مسار طلبات المستخدم السابقة: ${userGoals.join(' ➔ ')}\n` +
        `- القرارات والحلول التي اعتمدت سابقاً: ${aiDecisions.join(' | ')}\n` +
        `[توجيه]: التزم بهذا السياق التراكمي بدقة. آخر ${cfg.recentCount} رسائل التالية هي النص الحرفي المباشر.`;

      if (memoryDigest.length > cfg.maxBriefingChars) {
        memoryDigest = memoryDigest.slice(0, cfg.maxBriefingChars) + '...';
      }
      return memoryDigest;
    },

    async buildSystemPrompt(userText = '', attachments = [], conv = null, tier = 'MID') {
      if (!InstructionManager.files || !InstructionManager.files.length) {
        await InstructionManager.load();
      }
      const basePrompt = InstructionManager.assemblePrompt(userText, attachments, tier);
      const briefing = this.generateBriefing(conv, tier);
      if (!briefing) return basePrompt;
      return `${basePrompt}\n\n═══════════════════════════════════════════════════════════════\n${briefing}\n═══════════════════════════════════════════════════════════════\n(هذه خلاصة ذكية للمحادثة الكاملة — استخدمها كسياق كأنك كنت حاضراً من البداية. آخر ${this.getAdaptiveConfig(tier).recentCount} رسائل التالية هي النص الحرفي الأحدث)`;
    },

    async sendMessage(userText) {
      const hasAttachments = state.attachments && state.attachments.length > 0;
      if (!userText.trim() && !hasAttachments) return;
      if (state._cooldownUntil && Date.now() < state._cooldownUntil) {
        MessageRenderer.showToast('⏳ ثانية واحدة...', 'info');
        return;
      }
      if (state.isStreaming || state.sendInFlight || state.cacheOperationInFlight) {
        MessageRenderer.showToast('⏳ انتظر انتهاء الرد الحالي قبل إرسال رسالة جديدة', 'info');
        return;
      }
      // create conv BEFORE locking — otherwise first message swallows (newConversation blocked by sendInFlight)
      if (!state.activeConvId) StateController.newConversation();
      let conv = StateController.getActiveConv();
      if (!conv) {
        // fallback create directly if still null
        const id = generateId();
        conv = { id, title: 'محادثة جديدة', messages: [], mode: state.currentMode, isDev: false, createdAt: new Date().toISOString() };
        state.conversations.unshift(conv);
        state.activeConvId = id;
        try{ localStorage.setItem('activeConvId', id); }catch{}
        StateController.save();
      }
      state.sendInFlight = true;
      state._lastSendStart = Date.now();

      let { textForPayload, currentAttachments } = this.preparePayload(userText);
      // ── show user message instantly (fix 3-4s delay) ──
      const _displayText = (userText.trim() || textForPayload).slice(0,1200);
      const _earlyUserMsg = StateController.addMessage('user', _displayText, null, currentAttachments);
      if(_earlyUserMsg) MessageRenderer.appendMessage(_earlyUserMsg);
      // clear attachment UI now
      state.attachments = [];
      const _pcEarly = document.getElementById('attachment-preview-container');
      if(_pcEarly){ _pcEarly.classList.add('hidden'); _pcEarly.innerHTML=''; }
      UIEngine.updateSendBtnState();
      MessageRenderer.scrollToBottom();
      // ── Bank/OTP protection: never store or sync sensitive ──
      const _sensitiveRe = /\b\d{6}\b|\b\d{4}[\s-]?\d{4}[\s-]?\d{4}[\s-]?\d{4}\b|كلمة.*سر.*بنك|OTP|CVV|رمز.*تحقق/i;
      let _isSensitive = _sensitiveRe.test(textForPayload);
      if(_isSensitive){
        try{ MessageRenderer.showToast('⚠️ تم اكتشاف بيانات حساسة — لن تُزامن للمستودع', 'error'); }catch{}
        textForPayload = textForPayload.replace(_sensitiveRe, '[REDACTED]');
      }
      // Web Browse + Live Search + RAG-lite enrichment (non-blocking for UI, but needed for AI context)
      let enrichedPayload = textForPayload;
      try {
        if (WebSearchEngine && WebSearchEngine.isWebSearchIntent(textForPayload)) {
          MessageRenderer.setThinkingStage('🌐 البحث في الويب...');
          const searchResults = await WebSearchEngine.search(textForPayload);
          if (searchResults && searchResults.length > 0) {
            const formatted = searchResults.map((r, i) => `${i + 1}. [${r.title}]: ${r.snippet} (المصدر: ${r.url})`).join('\n\n');
            enrichedPayload += `\n\n[🌐 نتائج البحث الحي من الويب]:\n${formatted}\n--- استخدم هذه النتائج الحديثة لتقديم إجابة دقيقة ومحدثة مع ذكر المصادر عند اللزوم ---\n`;
          }
        }
      } catch(e) {}
      try {
        const urls=[...enrichedPayload.matchAll(/https?:\/\/[^\s"']+/g)].map(m=>m[0]).slice(0,1);
        for(const u of urls){ try{ const r=await fetch(`https://api.allorigins.win/raw?url=${encodeURIComponent(u)}`,{signal:AbortSignal.timeout(2800)}); if(r.ok){ const t=await r.text(); enrichedPayload+=`\n\n--- محتوى الرابط ${u} ---\n${t.slice(0,2500)}\n---`; } }catch{} }
        const ragKeys=['index.html','style.css','app.js','dev.js','dev_style.css','config.js','github.js','instructions.json'];
        const hit=ragKeys.filter(k=> enrichedPayload.toLowerCase().includes(k.toLowerCase()));
        for(const f of hit.slice(0,1)){ try{ const r=await fetch(`./${f}?t=${Date.now()}`); if(r.ok){ const t=await r.text(); enrichedPayload+=`\n\n--- ملف ${f} (مقتطف) ---\n${t.slice(0,2000)}\n---`; } }catch{} }
      }catch{}
      textForPayload = enrichedPayload;

      // ── Image intent: auto-generate (no picker) — priority = quality + cheapest ──
      if(window.ImageIntent && window.ImageIntent.isImageRequest(textForPayload)){
        // optional explicit model override via chat (e.g. "استخدم flux للصور")
        let explicitModel=null;
        try{
          const exp=window.ImageIntent.parseExplicit(textForPayload);
          if(exp && exp.model){
            let full=exp.model;
            try{
              const pool=await window.ImageGen.fetchImageModels();
              const low=exp.model.toLowerCase();
              const found=pool.find(m=> (m.id||'').toLowerCase().includes(low));
              if(found) full=found.id;
            }catch{}
            explicitModel=full;
            const isOnlySwitch=/^(غير|بدل|استخدم).*(موديل|للصور)/i.test(textForPayload.trim()) && textForPayload.trim().length<80;
            if(isOnlySwitch){
              // early message already shown
              state.sendInFlight=false; state.sendLock=false; state._lastSendStart=0; UIEngine.updateSendBtnState();
            }
          }
        }catch{}
        // early user message already shown — just reset flags
        state.sendInFlight=false; state.sendLock=false; state._lastSendStart=0; UIEngine.updateSendBtnState();
        const promptI=window.ImageIntent.extractPrompt(textForPayload);
        // priority queue: cheapest + quality first (flux/gpt-image-1 cheapest & good)
        const priority = explicitModel ? [explicitModel] : null;
        const first = priority ? priority[0] : (await window.ImageGen.getPriorityModel());
        await window.ImageGen.generate(first, promptI, conv);
        return;
      }

      // ── TTS delegation: text models → audio models ──
      if(window.TTSEngine && window.TTSEngine.isTTSRequest(textForPayload)){
        state.sendInFlight = false; state.sendLock = false; state._lastSendStart = 0; UIEngine.updateSendBtnState();
        await window.TTSEngine.handleTTSRequest(textForPayload, conv);
        state._lastSendStart = 0;
        return;
      }

      // ── SEEKAI direct (Other tab): priority, no fallback, no enabled check ──
      if(state.currentMode==='SEEKAI' && state.seekaiDirectModel){
        state.sendInFlight = false; state.sendLock = false; state._lastSendStart = 0; UIEngine.updateSendBtnState();
        // real thinking stages for Other models (tied to actual steps)
        const aiId2 = generateId();
        const aiMsg2 = {id:aiId2, role:'ai', content:'', timestamp:new Date().toISOString(), model:state.seekaiDirectModel};
        conv.messages.push(aiMsg2);
        state.isStreaming=true; state.isThinking=true; state.abortController=new AbortController();
        // ── Multi-Agent for Other (same logic as HIGH) ──
        if(state.isMultiAgentMode){
          try{
            // 3-agent consensus using SeekAI models: analyst→reviewer→synthesizer (selected)
            const keyS=window.ConfigVault?.getSeekAIKey?.()||'';
            const baseS=(window.ConfigVault?.getSeekAIUrl?.()||'https://seekai.cc').replace(/\/+$/,'');
            const seekFetch=async (model, msgs)=>{
              const rr=await fetch(baseS+'/v1/chat/completions',{method:'POST', headers:{'Authorization':`Bearer ${keyS}`,'Content-Type':'application/json'}, body: JSON.stringify({model, messages:msgs, stream:false}), signal: state.abortController.signal});
              const jj=await rr.json();
              if(jj.error) throw new Error(jj.error.message||JSON.stringify(jj));
              return jj.choices?.[0]?.message?.content||'';
            };
            MessageRenderer.startProgressiveThinking('Understanding');
            MessageRenderer.setThinkingStage('Analyst: kimi-k3');
            await new Promise(r=>setTimeout(r,300));
            const a1=await seekFetch('kimi-k3', [{role:'user', content: textForPayload+'\n[Analyst: provide concise draft]'}]);
            MessageRenderer.setThinkingStage('Auditor: Preferences & Rules');
            const aAud=await seekFetch('kimi-k3', [{role:'user', content: `طلب المستخدم: ${textForPayload}\nمسودة المحلل:\n${a1}\n[مدقق التفضيلات والتعليمات]: لخص التفضيلات الشخصية وسياق الشات وطابق المسودة مع تعليمات المجال ولغة الحوار/الأسلوب واذكر التقييم بدقة.`}]);
            MessageRenderer.setThinkingStage('Reviewer: deepseek-v4-pro');
            const a2=await seekFetch('deepseek-v4-pro', [{role:'user', content: `User: ${textForPayload}\nDraft: ${a1}\nAuditor: ${aAud}\n[Reviewer: critique in 2 bullets]`}]);
            MessageRenderer.setThinkingStage('Synthesizer: '+state.seekaiDirectModel);
            const final=await seekFetch(state.seekaiDirectModel, [{role:'user', content: `${textForPayload}\n\nAnalyst: ${a1}\nAuditor: ${aAud}\nReviewer: ${a2}\n[Synthesizer: final polished answer adhering to preferences and instructions]`}]);
            let contentF=String(final||'').replace(/https?:\/\/seekai\.cc[^\s]*/gi,'').trim();
            MessageRenderer.hideTyping(); state.isThinking=false;
            aiMsg2.content=contentF; MessageRenderer.appendMessage(aiMsg2); StateController.save();
            try{ window.UsageTracker?.record(aiMsg2.model,'seekai',textForPayload,contentF); }catch{}
          }catch(e){
            MessageRenderer.hideTyping(); state.isThinking=false;
            if(e.name!=='AbortError'){ aiMsg2.content='⚠️ SeekAI multi-agent: '+(e.message||'error'); MessageRenderer.appendMessage(aiMsg2); }
          }
          state.isStreaming=false; state.isThinking=false; state.abortController=null; state.sendInFlight=false; state.sendLock=false; state._lastSendStart=0; UIEngine.updateSendBtnState(); MessageRenderer.scrollToBottom(); StateController.save();
          return;
        }
        MessageRenderer.startProgressiveThinking('Understanding');
        UIEngine.updateSendBtnState();
        // stage 1: intent
        await new Promise(r=>setTimeout(r, 350));
        MessageRenderer.setThinkingStage('Analyzing context');
        // stage 2: connect
        MessageRenderer.setThinkingStage('Connecting to '+state.seekaiDirectModel);
        let r, j;
        try{
          const key=window.ConfigVault?.getSeekAIKey?.()||'';
          const base=(window.ConfigVault?.getSeekAIUrl?.()||'https://seekai.cc').replace(/\/+$/,'');
          MessageRenderer.setThinkingStage('Generating response');
          await new Promise(r=>setTimeout(r, 300));
          let content=j.choices?.[0]?.message?.content || j.choices?.[0]?.delta?.content || j.error?.message || JSON.stringify(j).slice(0,3000);
          if(j.error) throw new Error(content);
          // strip seekai footer/link injected by Other models
          content = String(content||'').replace(/https?:\/\/seekai\.cc[^\s]*/gi,'').replace(/.*seekai\.cc.*$/gmi,'').replace(/.*Powered by.*$/gmi,'').replace(/\n{3,}/g,'\n\n').trim();
          MessageRenderer.hideTyping(); state.isThinking=false;
          aiMsg2.content=content; MessageRenderer.appendMessage(aiMsg2); StateController.save();
          try{ window.UsageTracker?.record(aiMsg2.model,'seekai',textForPayload,content); }catch{}
        }catch(e){
          MessageRenderer.hideTyping(); state.isThinking=false;
          if(e.name==='AbortError') throw e;
          aiMsg2.content='⚠️ SeekAI `'+state.seekaiDirectModel+'`: '+(e.message||'error'); MessageRenderer.appendMessage(aiMsg2);
        }
        state.isStreaming=false; state.isThinking=false; state.abortController=null; state.sendInFlight=false; state.sendLock=false; state._lastSendStart=0; UIEngine.updateSendBtnState(); MessageRenderer.scrollToBottom(); StateController.save();
        return;
      }

      // early user message already shown — reuse it
      const userMsg = _earlyUserMsg;
      if (!userMsg) {
        state.isStreaming = false;
        state.abortController = null;
        state.sendInFlight = false;
        state.sendLock = false;
        UIEngine.updateSendBtnState();
        throw new Error('تعذر إضافة رسالتك للمحادثة الحالية');
      }

      const tier = state.currentMode || 'BALANCED';
      state.isStreaming = true;
      state.isThinking = true;
      state.abortController = new AbortController();
      MessageRenderer.startProgressiveThinking(tier==='HIGH'?'Deep Reasoning':'Analyzing');
      UIEngine.updateSendBtnState();
      debugCheckpoint('send-start', { tier, textLength: textForPayload.length });
      let systemPromptForCall;
      try {
        const promptTimeout = new Promise((_, reject) => setTimeout(() => reject(new Error('PROMPT_TIMEOUT')), 8000));
        systemPromptForCall = await Promise.race([
          this.buildSystemPrompt(textForPayload, currentAttachments, conv, tier),
          promptTimeout
        ]);
        debugCheckpoint('prompt-ready', { tier, promptLength: systemPromptForCall.length });
      } catch (err) {
        MessageRenderer.hideTyping();
        state.isThinking = false;
        state.isStreaming = false;
        state.abortController = null;
        state._lastSendStart = 0;
        UIEngine.updateSendBtnState();
        const errorMessage = {
          id: generateId(),
          role: 'ai',
          content: `⚠️ تعذر تجهيز الطلب: ${err.message === 'PROMPT_TIMEOUT' ? 'انتهت مهلة تجهيز التعليمات' : (err.message || 'خطأ غير معروف')}. يمكنك إعادة المحاولة.`,
          isError: true,
          timestamp: new Date().toISOString()
        };
        conv.messages.push(errorMessage);
        MessageRenderer.appendMessage(errorMessage);
        debugPrint(err, `Prompt preparation failed (${tier})`);
        UIEngine.updateSendBtnState();
        state.sendInFlight = false;
        state.sendLock = false;
        return;
      }
      const visImages = currentAttachments.filter(a=> a.type.startsWith('image/') && a.dataUrl);
      const userContent = visImages.length ? [{type:'text', text: textForPayload}, ...visImages.slice(0,3).map(a=>({type:'image_url', image_url:{url:a.dataUrl}}))] : textForPayload;
      const apiMessages = [
        { role: 'system', content: systemPromptForCall },
        ...conv.messages
          .filter(m => m.id !== userMsg.id)
          .slice(-this.getAdaptiveConfig(tier).recentCount)
          .map(m => ({ role: m.role === 'ai' ? 'assistant' : m.role, content: m.content })),
        { role: 'user', content: userContent }
      ];

      let fullContent = '';
      const aiMsgId = generateId();
      const aiMsgObj = {
        id: aiMsgId,
        role: 'ai',
        content: '',
        model: null,
        usedFallback: false,
        timestamp: new Date().toISOString()
      };
      conv.messages.push(aiMsgObj);

      const shouldObserve = !!state.isMultiAgentMode;
      const onModelEvent = (model, isFallback) => {
        aiMsgObj.model = model.name;
        aiMsgObj.provider = model.provider || 'groq';
        aiMsgObj.usedFallback = isFallback;

        if (isFallback) {
          MessageRenderer.setThinkingStage('Switching');
        }
      };

      // ── Multi-Agent active → same consensus logic for MID/FAST/HIGH/OTHER (copied as-is) ──
      if(state.isMultiAgentMode){
        try{
          await MultiAgentEngine.runConsensus(userText, textForPayload, apiMessages, aiMsgId, aiMsgObj, conv);
        }catch(e){
          if(e.name!=='AbortError') debugPrint(e, 'MultiAgent consensus failed');
        }
        StateController.save();
        // unlock and exit (observer will handle follow-up)
        MessageRenderer.hideTyping(); state.isThinking=false; state.isStreaming=false; state.abortController=null; state.sendInFlight=false; state.sendLock=false; state._lastSendStart=0; UIEngine.updateSendBtnState(); MessageRenderer.scrollToBottom(); try{ StateController.save(); }catch{}
        return;
      }
      try {
        debugCheckpoint('stream-start', { tier, messageCount: apiMessages.length });
        const stream = ModelEngine.chatWithFallback(state.currentMode, apiMessages, state.abortController.signal, onModelEvent);

        let msgRow = null;
        let pendingUpdate = false;
        let lastUpdateTs = 0;

        const scheduleUpdate = () => {
          if (pendingUpdate) return;
          pendingUpdate = true;
          // Batch DOM updates to the next animation frame to avoid long synchronous reflows
          requestAnimationFrame(() => {
            try {
              if (!msgRow) return;
              msgRow.innerHTML = MessageRenderer.parseMarkdown(fullContent);
              const isAr = /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/.test(fullContent);
              const parentRow = document.querySelector(`[data-id="${aiMsgId}"]`);
              if (parentRow) {
                parentRow.classList.toggle('is-rtl', isAr);
                parentRow.classList.toggle('is-ltr', !isAr);
              }
              msgRow.setAttribute('dir', isAr ? 'rtl' : 'ltr');
              msgRow.style.textAlign = isAr ? 'right' : 'left';
            } catch (err) {
              console.warn('Error updating AI msg DOM:', err && err.message);
            } finally {
              pendingUpdate = false;
              lastUpdateTs = Date.now();
            }
          });
        };

        for await (const { chunk, model, usedFallback } of stream) {
          fullContent += chunk;
          aiMsgObj.model = model.name;
          aiMsgObj.modelId = model.id;
          aiMsgObj.usedFallback = usedFallback;

          if (!msgRow) {
            MessageRenderer.hideTyping();
            state.isThinking = false;
            UIEngine.updateSendBtnState();
            MessageRenderer.appendMessage(aiMsgObj);
            msgRow = document.querySelector(`[data-id="${aiMsgId}"] .msg-content`);
            const aiElem = document.querySelector(`[data-id="${aiMsgId}"]`);
            if (aiElem && typeof aiElem.scrollIntoView === 'function') {
              aiElem.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            }
          }

          if (msgRow) {
            // If last update was recent, batch this chunk and let requestAnimationFrame handle it.
            const now = Date.now();
            if (now - lastUpdateTs > 80) {
              scheduleUpdate();
            } else {
              // ensure we schedule eventually
              scheduleUpdate();
            }
          }
        }
        // final flush after stream completes
        if (msgRow && !pendingUpdate) scheduleUpdate();
        // Ensure thinking flow is hidden and no glow remains after strong model finishes
        try { MessageRenderer.hideTyping(); document.getElementById('thinking-flow')?.remove(); document.querySelectorAll('.input-container.thinking').forEach(el=> el.classList.remove('thinking')); document.querySelectorAll('.flow-dot').forEach(d=> d.style.animation='none'); } catch {}

        if (fullContent.includes('---BEGIN_INSTRUCTION_UPDATE---') || fullContent.includes('"title"') && fullContent.includes('"content"')) {
          InstructionManager.handleAutoInstructionUpdate(fullContent);
          const cleanText = fullContent.replace(/---BEGIN_INSTRUCTION_UPDATE---[\s\S]*?---END_INSTRUCTION_UPDATE---/g, '').replace(/```json\s*\{[\s\S]*?"title"[\s\S]*?\}\s*```/g, '').trim();
          if (cleanText) {
            aiMsgObj.content = cleanText;
            if (msgRow) msgRow.innerHTML = MessageRenderer.parseMarkdown(cleanText);
          } else {
            aiMsgObj.content = fullContent;
            if (msgRow) msgRow.innerHTML = MessageRenderer.parseMarkdown(fullContent) + '<div style="margin-top:8px; font-size:12px; color:var(--accent-color);">✅ تم حفظ التعليمة — يمكنك مراجعتها في الإعدادات → التعليمات</div>';
          }
        } else {
          aiMsgObj.content = fullContent;
          const leakPat = /AVAILABLE_INSTRUCTION_FOLDERS|instruction_editing_protocol|50 توجيه|هوية المحرك.*Fast Mode/i;
          if(leakPat.test(aiMsgObj.content)){
            aiMsgObj.content = 'التعليمات الداخلية خاصة بالنظام ولا يمكن عرضها. أخبرني ماذا تريد أن تعدل أو تضيف وسأساعدك مباشرة.';
            if(msgRow) msgRow.innerHTML = MessageRenderer.parseMarkdown(aiMsgObj.content);
          }
        }
        // Skill previews: slides / mindmap — show preview button if JSON detected
        try {
          const slidesMatch = fullContent.match(/```json\s*([\s\S]*?"slides"[\s\S]*?)\s*```/);
          if (slidesMatch && msgRow) {
            const sData = JSON.parse(slidesMatch[1]);
            if (sData.slides && Array.isArray(sData.slides)) {
              const btn = `<button class="slides-launch-btn" data-slides="${encodeURIComponent(JSON.stringify(sData.slides))}" onclick="window._openSlides(decodeURIComponent(this.dataset.slides))">📊 عرض الشرائح التفاعلية</button>`;
              msgRow.innerHTML += btn;
            }
          }
          if (fullContent.includes('mindmap') || fullContent.includes('Mind Map')) {
            // mindmap preview is handled via parseMarkdown tree, no extra action needed
          }
        } catch {}
        StateController.save();
        try { UsageTracker.record(aiMsgObj.modelId || aiMsgObj.model, aiMsgObj.provider || 'groq', textForPayload, fullContent); } catch {}

      } catch (err) {
        MessageRenderer.hideTyping();
        state.isThinking = false;
        UIEngine.updateSendBtnState();
        if (err.name !== 'AbortError') {
          debugPrint(err, `Chat request failed (${state.currentMode || 'MID'})`);
          // Generic giant-model error handling: always print error in chat after thinking phase, never freeze
          const errText = (err && err.message) ? String(err.message) : 'خطأ غير معروف';
          if (!fullContent.trim()) {
            aiMsgObj.content = `⚠️ تعذر استلام الرد من نماذج ${state.currentMode || 'MID'}: ${errText}\n\nيمكنك المحاولة مرة أخرى أو التبديل لوضع Balanced/FAST.`;
            aiMsgObj.isError = true;
            // Ensure the placeholder bubble exists and is replaced with error bubble
            try { MessageRenderer.appendMessage(aiMsgObj); } catch (e) { console.warn('[render error msg failed]', e); }
            try { StateController.save(); } catch {}
          } else {
            // Partial content arrived before error — keep what we have and append error note
            aiMsgObj.content = fullContent + `\n\n---\n⚠️ انقطع الاتصال أثناء الاستجابة: ${errText}`;
            try { StateController.save(); } catch {}
          }
          MessageRenderer.showToast('❌ ' + errText.slice(0,180), 'error');
        }
      } finally {
        // Guaranteed unlock — prevents freeze/ swallowed messages
        MessageRenderer.hideTyping();
        state.isThinking = false;
        state.isStreaming = false;
        state.abortController = null;
        state.sendInFlight = false;
        state.sendLock = false;
        state.cacheOperationInFlight = false;
        state._lastSendStart = 0;
        state._cooldownUntil = Date.now() + 450;
        UIEngine.updateSendBtnState();
        MessageRenderer.scrollToBottom();
        try { StateController.save(); } catch {}
        // Observer agents: follow-up review AFTER main level response (non-blocking, prevents freeze) — 650ms gap to avoid overlap
        if (shouldObserve && fullContent && !aiMsgObj.isError) {
          setTimeout(() => {
            try { if (window.ObserverEngine) window.ObserverEngine.observe(userText, fullContent, tier, aiMsgId, conv); } catch (e) { console.warn('[Observer]', e); }
          }, 650);
        }
      }
    }
  };

  // ─────────────────────────────────────────────────────────────────
  // 8. MULTI-AGENT COLLABORATIVE CONSENSUS ENGINE — Extracted to modules/chat-engine.js
  // ─────────────────────────────────────────────────────────────────
  const MultiAgentEngine = window.MultiAgentEngine || {
    async runConsensus(userText, textForPayload, apiMessages, aiMsgId, aiMsgObj, conv) {
      MessageRenderer.showTyping('جاري بدء تشاور الوكلاء...');

      let msgRow = null;
      const getOrCreateRow = () => {
        if (!msgRow) {
          MessageRenderer.hideTyping();
          MessageRenderer.appendMessage(aiMsgObj);
          msgRow = document.querySelector(`[data-id="${aiMsgId}"] .msg-content`);
        }
        return msgRow;
      };

      const renderLiveUI = (steps, finalContent = '', isThinking = true) => {
        const row = getOrCreateRow();
        if (!row) return;

        const isDone = !isThinking && steps.every(s => s.status.includes('✓') || s.status.includes('معتمد') || s.status.includes('تجاوز'));
        const okC = steps.filter(s => /✓|مكتمل|معتمد|Done|Approved/i.test(s.status)).length;
        const warnC = steps.filter(s => s.status.includes('تجاوز') || s.hasError).length;
        const statusBadgeCls = isDone ? (warnC > 0 ? 'warn' : 'ok') : 'running';
        const badgeLabel = isDone ? (warnC > 0 ? `⚠️ ${warnC} ملاحظات` : '✓ معتمد (0 أخطاء)') : '⏳ جاري التشاور...';

        const pipelineTrackHtml = `
          <div class="audit-pulse-track">
            ${steps.map((s, i) => {
              const isCompleted = s.status.includes('✓') || s.status.includes('Done') || s.status.includes('معتمد');
              const isActive = s.status.includes('نشط') || s.status.includes('Active');
              const isWarn = s.status.includes('تجاوز') || s.hasError;
              const nodeClass = isCompleted ? (isWarn ? 'failed' : 'completed') : (isActive ? 'active' : 'pending');
              return `
                <div class="audit-pulse-node ${nodeClass}" title="${MessageRenderer.escapeHtml(s.title)}">
                  <span class="audit-pulse-dot"></span>
                  <span class="audit-pulse-label">${i + 1}. ${MessageRenderer.escapeHtml(s.shortName || s.title.split(' ')[0])}</span>
                </div>
                ${i < steps.length - 1 ? `<div class="audit-pulse-connector ${isCompleted ? 'completed' : ''}"></div>` : ''}
              `;
            }).join('')}
          </div>
        `;

        const bulletsHtml = steps.filter(s => s.summary && s.status !== 'في الانتظار').map(s => {
          const isWarn = s.status.includes('تجاوز') || s.hasError;
          return `
            <li class="peer-bullet ${isWarn ? 'warn' : 'ok'}" dir="rtl">
              <span class="peer-bullet-dot"></span>
              <span class="peer-bullet-text"><strong>${MessageRenderer.escapeHtml(s.title.split('(')[0].trim())}:</strong> ${MessageRenderer.escapeHtml(s.summary)}</span>
            </li>
          `;
        }).join('');

        const boxHtml = `
          <div class="multi-agent-box proposal-audit-section" id="box-${aiMsgId}">
            <div class="proposal-audit-header" onclick="this.closest('.multi-agent-box')?.classList.toggle('collapsed')">
              <div class="dev-peer-title">
                <span class="dev-peer-icon">👥</span>
                <span class="dev-peer-name">تشاور الوكلاء (${steps.length} وكلاء)</span>
                <span class="dev-peer-badge ${statusBadgeCls}">${badgeLabel}</span>
              </div>
              <span class="dev-peer-toggle">▾</span>
            </div>
            <div class="observer-details dev-peer-body">
              ${pipelineTrackHtml}
              <ul class="peer-bullets-list">
                ${bulletsHtml || `<li class="peer-bullet ok" dir="rtl"><span class="peer-bullet-dot"></span><span class="peer-bullet-text">جاري بدء مراحل التشاور والتدقيق...</span></li>`}
              </ul>
              ${isDone ? `
                <div class="peer-actions-bar">
                  <button class="peer-action-btn retry-btn" onclick="window._sendToLLM(this)"><span>🚀</span><span>Send to LLM</span></button>
                  <button class="peer-action-btn apply-btn" onclick="window._applyObserverSuggestion(this.closest('.multi-agent-box')?.dataset?.review||'', this)"><span>⚡</span><span>Apply</span></button>
                </div>
              ` : ''}
            </div>
          </div>
        `;

        const parsedFinal = finalContent ? MessageRenderer.parseMarkdown(finalContent) : (isThinking ? '<div style="color:var(--text-dim); font-size:13px; padding:4px;">⏳ جاري صياغة القرار النهائي المعتمد...</div>' : '');
        row.innerHTML = boxHtml + parsedFinal;

        const isAr = /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/.test(finalContent || userText);
        const parentRow = document.querySelector(`[data-id="${aiMsgId}"]`);
        if (parentRow) {
          parentRow.classList.toggle('is-rtl', isAr);
          parentRow.classList.toggle('is-ltr', !isAr);
        }
      };

      const isTrivialMA = /^(السلام عليكم|مرحبا|هلا|اهلا|انت (كويس|عامل ايه)|كيف حالك|ترجم( كلمة)?$|ضيف تشكيل|عدل الجملة)/i.test(textForPayload.trim()) || textForPayload.trim().length < 22;
      if(isTrivialMA){
        // bypass for trivial — direct single FAST call, no 6 stages
        const stream0 = ModelEngine.chatWithFallback('FAST', apiMessages, state.abortController.signal, () => {});
        let out=''; for await(const {chunk} of stream0) { out+=chunk; renderLiveUI(steps, out, false); }
        steps.forEach(s=>{ s.status='✓ تجاوز تريفيال'; s.summary='Trivial bypass'; });
        renderLiveUI(steps, out, false);
        aiMsgObj.content=out; aiMsgObj.multiAgentSteps=steps; StateController.save(); return;
      }
      const steps = [
        { id: 1, icon: '💡', title: 'المحلل الاستراتيجي (Strategic Analyst)', shortName: 'المحلل', status: 'نشط الآن', summary: 'جاري دراسة المسألة واقتراح التحليل والمسودة الأولية...' },
        { id: 2, icon: '🎯', title: 'مدقق التفضيلات والتعليمات (Preferences & Domain Auditor)', shortName: 'التفضيلات', status: 'في الانتظار', summary: 'بانتظار المسودة لمطابقتها مع التفضيلات وسياق التعليمات والهدف الجوهري...' },
        { id: 3, icon: '🔍', title: 'الناقد المنطقي (Critical Reviewer)', shortName: 'الناقد', status: 'في الانتظار', summary: 'بانتظار فحص المسودة وتدقيق الثغرات...' },
        { id: 4, icon: '👑', title: 'المقرر النهائي (Chief Synthesizer)', shortName: 'المقرر', status: 'في الانتظار', summary: 'بانتظار التقارير للصياغة المعتمدة...' }
      ];

      renderLiveUI(steps, '', true);

      // --- STAGE 1: Strategic Analyst ---
      const stage1Messages = [
        ...apiMessages.slice(0, -1),
        {
          role: 'user',
          content: `${textForPayload}

[DIRECTIVE TO STRATEGIC ANALYST]:
1. Understand the exact problem from the user's perspective (client/end-user vs server admin).
2. DO NOT assume the user runs, owns, or configures the backend/server/hosting (e.g. nginx, permissions, chmod, apache) unless explicitly stated.
