  border: none;
  color: #fff;
  padding: 2px 0;
  border-radius: 0;
  max-width: 80%;
  width: fit-content;
  font-size: 14.5px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}

.message-row.ai {
  align-self: flex-start;
  align-items: stretch;
  width: 100%;
}

.message-row.ai .msg-content {
  color: var(--text-main);
  font-size: 14.5px;
  line-height: 1.65;
  word-break: break-word;
}

.message-row.is-rtl,
.message-row.user.is-rtl,
.message-row.ai.is-rtl {
  direction: rtl;
  text-align: right;
}

.message-row.is-ltr,
.message-row.user.is-ltr,
.message-row.ai.is-ltr {
  direction: ltr;
  text-align: left;
}

.message-row.user.is-rtl .msg-content {
  direction: rtl;
  text-align: right;
}

.message-row.user.is-ltr .msg-content {
  direction: ltr;
  text-align: left;
}

.message-copy-bar {
  width: 80%;
  display: flex;
  justify-content: flex-start;
  margin-top: 3px;
  direction: ltr;
}
.user-copy-outside {
  width: 24px;
  height: 22px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-subtle);
  border-radius: 7px;
  background: transparent;
  color: var(--text-dim);
  cursor: pointer;
  opacity: 0.72;
}
.user-copy-outside:hover {
  color: var(--text-main);
  border-color: rgba(255, 255, 255, 0.2);
  opacity: 1;
}

.message-row.ai.is-rtl .msg-content {
  direction: rtl;
  text-align: right;
  unicode-bidi: plaintext;
}

.message-row.ai.is-ltr .msg-content {
  direction: ltr;
  text-align: left;
  unicode-bidi: plaintext;
}

.message-line {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  width: 100%;
}
.message-speaker {
  flex: 0 0 24px;
  width: 24px;
  height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-subtle);
  border-radius: 7px;
  background: rgba(255,255,255,.04);
  font-size: 13px;
  line-height: 1;
  user-select: none;
}
.user-speaker { color: #93c5fd; }
.ai-speaker { color: #c4b5fd; }
.message-row.user .message-line {
  width: 100%;
  justify-content: flex-end;
}
.message-row.user .message-line .msg-content {
  max-width: none;
}

/* ─── Code Blocks & Diff Previews (Always LTR) ─── */
pre, code {
  direction: ltr !important;
  text-align: left !important;
  unicode-bidi: isolate !important;
}
pre {
  background: #0a0a0d !important;
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  padding: 14px;
  overflow-x: auto;
  margin: 10px 0;
  font-family: var(--font-mono) !important;
  font-size: 13px !important;
  color: #e5e7eb;
}

code {
  font-family: var(--font-mono);
  font-size: 0.9em;
  background: rgba(255, 255, 255, 0.08);
  padding: 2px 6px;
  border-radius: 4px;
  color: #fbbf24;
}

pre code {
  background: transparent !important;
  padding: 0 !important;
  color: inherit !important;
}

