  color: #a5f3fc !important;
  direction: ltr !important;
  text-align: left !important;
}

/* ─── Modern Circular Pull To Refresh Indicator ─── */
.pull-refresh-indicator {
  position: fixed;
  top: 14px;
  left: 50%;
  transform: translate(-50%, -80px) scale(0.85);
  width: 42px;
  height: 42px;
  background: rgba(30, 30, 34, 0.96);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-dev);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.7);
  z-index: 9999;
  opacity: 0;
  pointer-events: none;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.2s ease;
}

.pull-refresh-indicator.pull-bottom {
  top: auto;
  bottom: 85px;
  transform: translate(-50%, 80px) scale(0.85);
}

.pull-refresh-indicator.visible {
  opacity: 1;
}

.pull-refresh-indicator.refreshing {
  opacity: 1;
  transform: translate(-50%, 20px) scale(1);
}

.pull-refresh-indicator.pull-bottom.refreshing {
  opacity: 1;
  transform: translate(-50%, -18px) scale(1);
}

.pull-refresh-spinner {
  width: 21px;
  height: 21px;
  color: var(--accent-dev);
  transition: transform 0.08s linear;
}

.pull-refresh-indicator.refreshing .pull-refresh-spinner {
  animation: modernSpin 0.7s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

@keyframes modernSpin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* ─── Bottom Refresh Confirmation Modal ─── */
.bottom-refresh-modal {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.68);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
}

.bottom-refresh-modal.show {
  opacity: 1;
  pointer-events: auto;
}

.bottom-refresh-card {
  background: #18181c;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 18px;
  padding: 22px 24px;
  max-width: 340px;
  width: 100%;
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.85);
  text-align: center;
  direction: ltr;
  transform: scale(0.92);
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.bottom-refresh-modal.show .bottom-refresh-card {
  transform: scale(1);
}

.bottom-refresh-header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: #fff;
  font-weight: 700;
  font-size: 16px;
}

.bottom-refresh-desc {
  font-size: 13.5px;
  color: var(--text-muted);
  margin: 10px 0 18px;
  line-height: 1.5;
}

.bottom-refresh-actions {
  display: flex;
  gap: 10px;
  justify-content: center;
}

.btn-refresh-confirm {
  flex: 1;
  padding: 10px 16px;
  background: linear-gradient(135deg, #f59e0b, #d97706);
  color: #fff;
  border: none;
  border-radius: 10px;
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  transition: transform 0.15s ease, opacity 0.15s ease;
}

.btn-refresh-confirm:hover {
  opacity: 0.95;
  transform: translateY(-1px);
}

.btn-refresh-cancel {
  flex: 1;
  padding: 10px 16px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-muted);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.btn-refresh-cancel:hover {
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
}

/* ─── Ultra-Modern Developer Terminal / Code Card ─── */
.dev-terminal-card {
  margin: 14px 0;
  background: #15151a;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6), 0 0 15px rgba(0, 0, 0, 0.35);
  direction: ltr !important;
  text-align: left !important;
  font-family: var(--font-sans);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.dev-terminal-card:hover {
  border-color: rgba(245, 158, 11, 0.35);
  box-shadow: 0 14px 38px rgba(0, 0, 0, 0.7), 0 0 20px rgba(245, 158, 11, 0.12);
}

.terminal-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 14px;
  background: #1d1d24;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  gap: 10px;
}

.terminal-header-left {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  overflow: hidden;
}

.terminal-icon-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 7px;
  background: rgba(245, 158, 11, 0.15);
  border: 1px solid rgba(245, 158, 11, 0.35);
  color: #fbbf24;
  border-radius: 6px;
  font-size: 11.5px;
  font-weight: 700;
  font-family: var(--font-mono);
  line-height: 1.2;
  flex-shrink: 0;
}

.terminal-lang-title {
  font-size: 13px;
  font-weight: 700;
  color: #f3f4f6;
  white-space: nowrap;
  flex-shrink: 0;
}

.terminal-cmd-preview {
  font-size: 11.5px;
  color: #9ca3af;
  font-family: var(--font-mono);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  opacity: 0.85;
}

.terminal-header-right {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.terminal-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 10px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #e5e7eb;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
  font-family: var(--font-sans);
}

.terminal-action-btn:hover {
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  border-color: rgba(255, 255, 255, 0.25);
}

.terminal-action-btn.copy-btn:hover {
  background: rgba(245, 158, 11, 0.18);
  border-color: rgba(245, 158, 11, 0.4);
  color: #fbbf24;
}

.terminal-card-body {
  padding: 12px 14px;
  background: #0d0d10;
  overflow-x: auto;
  transition: max-height 0.25s ease;
}

.terminal-card-body.collapsed {
  max-height: 125px;
  overflow-y: hidden;
  position: relative;
}

.terminal-card-body.collapsed::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 48px;
  background: linear-gradient(to bottom, transparent, #0d0d10);
  pointer-events: none;
}

.terminal-card-body pre {
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  overflow: visible !important;
}

.terminal-card-body pre code {
  display: block;
  font-family: var(--font-mono) !important;
  font-size: 13px !important;
  line-height: 1.6 !important;
  color: #e5e7eb !important;
  background: transparent !important;
  padding: 0 !important;
  white-space: pre !important;
  tab-size: 2;
}

.terminal-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 14px;
  background: #191920;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
}

.terminal-footer-status {
  display: flex;
  align-items: center;
  gap: 6px;
  direction: ltr;
  text-align: left;
}

.terminal-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2.5px 8px;
  background: rgba(16, 185, 129, 0.14);
  border: 1px solid rgba(16, 185, 129, 0.35);
  color: #34d399;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 700;
  font-family: var(--font-mono);
}

.terminal-footer-meta {
  font-size: 11.5px;
  color: var(--text-dim);
  font-family: var(--font-mono);
}

/* ─── Floating Input Bar (Identical to User Chatbox) ─── */
#input-section {
  padding: 6px 14px 18px;
  padding-bottom: max(18px, env(safe-area-inset-bottom, 18px));
  background: transparent;
  flex-shrink: 0;
  z-index: 25;
  width: 100%;
  display: flex;
  justify-content: center;
}

.input-container {
  max-width: 768px;
  width: 100%;
  margin: 0 auto;
  background: #17171d;
  border: 1px solid var(--border-subtle);
  border-radius: 26px;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
  position: relative;
  overflow: visible;
}

.input-container:focus-within {
  border-color: rgba(245, 158, 11, 0.45);
  box-shadow: 0 8px 32px rgba(245, 158, 11, 0.12), 0 0 0 1px rgba(245, 158, 11, 0.25);
}

/* Thinking glow removed per request */
.input-container.thinking{border-color:var(--border-subtle) !important;box-shadow:0 8px 32px rgba(0,0,0,0.5) !important;animation:none !important}
.input-container.thinking::before{display:none !important}

.typing-bubble {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 2px 0 !important;
  backdrop-filter: none !important;
}

/* Thinking flow — no background, icon left + sentence, smooth upward dots (same as chat) */
.thinking-flow {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 8px;
  padding-left: 2px;
}
.thinking-flow {
  border-left: 1px solid var(--border-subtle);
  padding-left: 14px;
}
.thinking-flow-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  color: var(--text-dim);
  opacity: 0;
  transform: translateY(6px);
  animation: thinkingFlowIn 0.35s ease forwards;
  position: relative;
}
.thinking-flow-item .flow-dot{
  position:absolute;
  left:-16px;
  top:7px;
  width:7px;
  height:7px;
  border-radius:50%;
  background:var(--accent-dev);
  box-shadow:0 0 6px var(--accent-dev-glow);
  display:none;
}
.thinking-flow-item.reached .flow-dot{display:block;animation:flowDotPulse 1.1s ease-in-out infinite}
/* Highlight by importance — dev also */
.hl-important { color: var(--hl-important); font-weight: 700; }
.hl-critical { color: var(--hl-critical); font-weight: 700; }
.hl-success { color: var(--hl-success); font-weight: 700; }
.hl-info { color: var(--hl-info); font-weight: 600; }
.hl-keyword { color: var(--hl-keyword); font-weight: 600; background: rgba(167,139,250,0.12); padding: 1px 4px; border-radius: 4px; }

.thinking-flow-item .flow-icon {
  font-size: 13px;
  flex-shrink: 0;
  width: 16px;
  text-align: center;
}
.thinking-flow-item .flow-text {
  flex: 1;
  line-height: 1.4;
}
.thinking-flow-item .flow-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--accent-dev);
  opacity: 0;
  flex-shrink: 0;
}
.thinking-flow-item.reached .flow-dot{
  opacity:0.9;
  animation: flowDotPulse 1.2s ease-in-out infinite;
}
@keyframes flowDotPulse{
  0%{transform:scale(0.8);opacity:0.5}
  50%{transform:scale(1.3);opacity:1}
  100%{transform:scale(0.8);opacity:0.5}
}
@keyframes thinkingFlowIn {
  to { opacity: 1; transform: translateY(0); }
}
@keyframes flowDotUp {
  0% { transform: translateY(0); opacity: 0.3; }
  50% { transform: translateY(-5px); opacity: 1; }
  100% { transform: translateY(-10px); opacity: 0; }
}

.chat-textarea {
  width: 100%;
  background: transparent;
  border: none;
  outline: none;
  color: var(--text-main);
  font-family: var(--font-sans);
  font-size: 15.5px;
  line-height: 1.5;
  resize: none;
  min-height: 26px;
  max-height: 200px;
  padding: 2px 0 6px;
  overflow-y: hidden;
  unicode-bidi: plaintext;
  box-sizing: border-box;
}

.chat-textarea::placeholder {
  color: #52525b;
}

/* Fix: تعليمات المطور لون النص أسود → أبيض */
.dev-textarea,
#dev-prompt-textarea,
#direct-code-editor {
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
}
.dev-textarea::placeholder,
#dev-prompt-textarea::placeholder,
#direct-code-editor::placeholder {
  color: #9ca3af !important;
}

/* Bottom Controls Row inside Container */
.input-bottom-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.input-bottom-left {
  display: flex;
  align-items: center;
  gap: 8px;
