/* Electric Send Button (⚡) */
.claude-send-btn {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  color: #71717a;
  border: none;
  cursor: not-allowed;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s cubic-bezier(0.16, 1, 0.3, 1);
  pointer-events: none;
  opacity: 0.45;
  box-shadow: none;
}

.claude-send-btn.active {
  background: linear-gradient(135deg, #f59e0b, #d97706) !important;
  color: #000 !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  opacity: 1 !important;
  box-shadow: 0 3px 12px rgba(245, 158, 11, 0.45) !important;
}

.claude-send-btn.active:hover {
  filter: brightness(1.1);
  transform: scale(1.08);
}

.claude-send-btn.active:active {
  transform: scale(0.96);
}

.claude-send-btn.streaming-stop {
  background: #ef4444 !important;
  color: #ffffff !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  opacity: 1 !important;
  box-shadow: 0 0 16px rgba(239, 68, 68, 0.6) !important;
  animation: devStopPulse 1.2s ease-in-out infinite alternate;
}

.claude-send-btn.streaming-stop:hover {
  background: #dc2626 !important;
  transform: scale(1.08);
}

@keyframes devStopPulse {
  0% {
    transform: scale(0.96);
    box-shadow: 0 0 8px rgba(239, 68, 68, 0.4);
  }
  100% {
    transform: scale(1.04);
    box-shadow: 0 0 18px rgba(239, 68, 68, 0.8);
  }
}

