/* ─── Toast Container (above input bar) ─── */
#toast-container {
  position: fixed;
  bottom: calc(86px + env(safe-area-inset-bottom, 0px));
  right: 50%;
  transform: translateX(50%);
  left: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 9999;
  max-width: calc(100vw - 24px);
  pointer-events: none;
}

.toast {
  padding: 10px 16px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 8px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.5);
  animation: fadeIn 0.2s ease;
  backdrop-filter: blur(8px);
}

.toast.success { background: rgba(16, 185, 129, 0.9); color: #fff; }
.toast.error { background: rgba(244, 63, 94, 0.9); color: #fff; }
.toast.info { background: rgba(30, 41, 59, 0.95); border: 1px solid var(--border-subtle); color: #fff; }
.toast.warning { background: rgba(245, 158, 11, 0.9); color: #000; }

