  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  user-select: none;
}

.emerald-sync-pill-btn:hover {
  background: rgba(16, 185, 129, 0.22);
  border-color: rgba(16, 185, 129, 0.65);
  box-shadow: 0 0 18px rgba(16, 185, 129, 0.35);
  color: #6ee7b7;
  transform: translateY(-1px);
}

.emerald-sync-pill-btn:active {
  transform: translateY(0);
}

.emerald-sync-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #10b981;
  box-shadow: 0 0 6px #10b981;
  transition: background-color 0.2s ease;
}

.emerald-sync-pill-btn .sync-svg-icon {
  stroke: #34d399;
  transition: transform 0.4s ease, stroke 0.2s ease;
}

.emerald-sync-pill-btn:hover .sync-svg-icon {
  stroke: #ffffff;
  transform: rotate(45deg);
}

.emerald-sync-pill-btn.spinning {
  background: rgba(59, 130, 246, 0.16);
  border-color: rgba(59, 130, 246, 0.5);
  color: #93c5fd;
  box-shadow: 0 0 14px rgba(59, 130, 246, 0.25);
}

