  animation: modernSpin 0.75s infinite cubic-bezier(0.5, 0, 0.5, 1);
  stroke: #60a5fa;
}

@keyframes modernSpin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

